 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    frames = []
    colors = {v for row in grid for v in row if v}
    # A frame is a rectangular, solid, single-color perimeter (at least 3x3).
    for color in colors:
        for r1 in range(h - 2):
            for r2 in range(r1 + 2, h):
                for c1 in range(w - 2):
                    for c2 in range(c1 + 2, w):
                        if all(grid[r1][c] == color and grid[r2][c] == color for c in range(c1, c2 + 1)) and all(grid[r][c1] == color and grid[r][c2] == color for r in range(r1, r2 + 1)):
                            # Keep only the actual frame, not a larger accidental enclosure.
                            if all(grid[r][c] != color for r in range(r1 + 1, r2) for c in range(c1 + 1, c2)):
                                frames.append((r1, r2, c1, c2, color))
    # Remove duplicate candidates, if any.
    frames = list(dict.fromkeys(frames))
    frame_cells = {(r, c) for r1, r2, c1, c2, _ in frames for r in range(r1, r2 + 1) for c in range(c1, c2 + 1)}
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v and (r, c) not in frame_cells:
                counts[v] = counts.get(v, 0) + 1
    out = [[0] * w for _ in range(h)]
    for r1, r2, c1, c2, border in frames:
        for c in range(c1, c2 + 1):
            out[r1][c] = out[r2][c] = border
        for r in range(r1, r2 + 1):
            out[r][c1] = out[r][c2] = border
        ih, iw = r2 - r1 - 1, c2 - c1 - 1
        needed = (ih * iw + 1) // 2
        matches = [color for color, n in counts.items() if n == needed]
        if len(matches) == 1:
            fill = matches[0]
            for dr in range(ih):
                for dc in range(iw):
                    if (dr + dc) % 2 == 0:
                        out[r1 + 1 + dr][c1 + 1 + dc] = fill
    return out
